pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Roulette} from "../src/Roulette.sol";

contract InvMutTest is Test {
    Roulette c;

    function setUp() public {
        c = new Roulette{value: 10 ether}();
    }

    function testFuzz_property(uint256 ts, address actor) public {
        vm.assume(ts > 0);
        vm.assume(actor != address(c));
        vm.warp(ts);
        uint256 amount = 10 ether;
        vm.deal(actor, amount);
        vm.prank(actor);
        bool ok;
        (bool sent,) = address(c).call{value: amount}("");
        ok = sent;
        assertTrue(ok && c.pastBlockTime() == ts);
    }
}
